def fix(repo, rel, content):
    p = repo / rel
    if not p.exists(): sys.exit(f"[ERROR] {p} tidak ditemukan.")
    if p.read_text(encoding="utf-8") == content:
        print(f"  [skip]  {rel}")
        return
    p.write_text(content, encoding="utf-8")
    print(f"  [ok]    {rel}")

def main():
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument("--repo", default=".", help="Root repo avnc-test")
    repo = Path(ap.parse_args().repo).resolve()
    if not (repo / FLYOUT).exists():
        sys.exit("[ERROR] VirtualControllerKeyPropsFlyout.kt tidak ditemukan.")
    print(f"Repo: {repo}")
    fix(repo, FLYOUT, C_FLYOUT)
    fix(repo, STRINGS, C_STRINGS)
    print()
    print("Selesai!")
    print("  • Label Transparansi kini tampil benar dari awal (tidak ada %%)")
    print("  • Tombol Reset mengembalikan lebar=42dp, tinggi=42dp, transparansi=100%")

if __name__ == "__main__": main()
